<?= $this->section('content') ?>
<div class="mb-6"><h1 class="text-3xl font-bold tracking-[-.025em]">Applications</h1><p class="text-slate-500">Review weighted readiness assessments and make the final staff decision.</p></div>
<form method="get" class="card mb-6 grid gap-3 md:grid-cols-3 xl:grid-cols-5"><input class="field xl:col-span-2" name="search" value="<?= esc($filters['search'] ?? '') ?>" placeholder="Search applicant, app ID, or cat"><select class="field" name="status"><option value="">All decisions</option><?php foreach (['Under Review', 'Approved', 'Rejected'] as $status): ?><option value="<?= esc($status) ?>" <?= ($filters['status'] ?? '') === $status ? 'selected' : '' ?>><?= esc($status) ?></option><?php endforeach ?></select><select class="field" name="score_band"><option value="">All scores</option><option value="strong" <?= ($filters['score_band'] ?? '') === 'strong' ? 'selected' : '' ?>>80–100 Strong</option><option value="review" <?= ($filters['score_band'] ?? '') === 'review' ? 'selected' : '' ?>>60–79 Review</option><option value="low" <?= ($filters['score_band'] ?? '') === 'low' ? 'selected' : '' ?>>Below 60</option></select><div class="flex gap-2"><button class="btn btn-primary">Apply filters</button><a class="btn btn-ghost" href="<?= site_url('admin/applications') ?>">Clear</a></div></form>
<div class="card overflow-x-auto p-0"><table class="min-w-[860px] w-full text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3 text-left">Applicant</th><th class="px-4 py-3 text-left">Cat</th><th class="px-4 py-3 text-left">Readiness score</th><th class="px-4 py-3 text-left">Decision</th><th class="px-4 py-3 text-left">Submitted</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><?php foreach ($applications as $app): ?><?php $decision = $app['status'] ?? 'Under Review'; $rowTone = $decision === 'Approved' ? 'bg-slate-100 text-slate-500 opacity-75 hover:bg-slate-200' : ($decision === 'Rejected' ? 'bg-red-50 text-red-900 hover:bg-red-100' : 'hover:bg-slate-50'); $decisionTone = $decision === 'Approved' ? 'bg-slate-200 text-slate-700' : ($decision === 'Rejected' ? 'bg-red-100 text-red-700' : 'bg-violet-50 text-violet-700'); ?><tr class="border-t <?= $rowTone ?>"><td class="px-4 py-3"><div class="font-semibold <?= $decision === 'Rejected' ? 'text-red-900' : 'text-slate-900' ?>"><?= esc($app['full_name']) ?></div><div class="mt-0.5 text-xs">App <?= esc($app['application_id']) ?></div></td><td class="px-4 py-3"><?= esc($app['animal_name'] ?: $app['cat_description']) ?></td><td class="px-4 py-3"><span class="font-bold <?= $app['assessment_score'] === null ? 'text-slate-400' : ((float) $app['assessment_score'] >= 80 ? 'text-adopted-600' : ((float) $app['assessment_score'] >= 60 ? 'text-amber-600' : 'text-red-600')) ?>"><?= $app['assessment_score'] === null ? 'Provisional' : esc(number_format((float) $app['assessment_score'], 2)) . '%' ?></span><div class="mt-0.5 text-xs"><?= esc($app['assessment_status'] ?? '') ?></div></td><td class="px-4 py-3"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-bold <?= $decisionTone ?>"><?= esc($decision) ?></span></td><td class="px-4 py-3"><?= esc($app['submitted_at']) ?></td><td class="px-4 py-3 text-right"><a href="<?= site_url('admin/applications/' . $app['id']) ?>" class="inline-flex items-center gap-1.5 rounded-lg border border-rescue-200 bg-rescue-50 px-3 py-2 text-xs font-semibold text-rescue-700 hover:bg-rescue-100"><i data-lucide="file-text" class="h-4 w-4"></i>Review</a></td></tr><?php endforeach; ?></tbody></table><?php if (empty($applications)): ?><div class="p-10 text-center text-sm text-slate-500">No adoption applications match the selected filters.</div><?php endif; ?></div>
<?= $this->endSection() ?>
